import test from 'node:test';
import assert from 'node:assert/strict';
import { charge } from '../src/checkout.js';
test('retries one failed charge', async () => {
  let calls = 0;
  const result = await charge({ charge: async () => (++calls === 1 ? Promise.reject(new Error('retry')) : 'ok') }, {});
  assert.equal(result, 'ok');
  assert.equal(calls, 2);
});
